class HokagoIcon extends StatelessWidget {
  const HokagoIcon(this.name, {super.key, this.size = 22, this.color});
  final String name;
  final double size;
  final Color? color;

  @override
  Widget build(BuildContext context) {
    final body = _iconBodies[name];
    assert(body != null, 'no HokagoIcon body registered for "$name"');
    final tint = color ?? IconTheme.of(context).color ?? DefaultTextStyle.of(context).style.color ?? Colors.white;
    return SvgPicture.string(
      '<svg viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">$body</svg>',
      width: size,
      height: size,
      colorFilter: ColorFilter.mode(tint, BlendMode.srcIn),
    );
  }
}

/// ui/Logo.tsx's LogoMark — the multi-tone hokago mark, not tintable (it's
/// the actual illustrated logo, not a monoline icon), so no colorFilter.
class HokagoLogoMark extends StatelessWidget {
  const HokagoLogoMark({super.key, this.size = 22});
  final double size;

  @override
  Widget build(BuildContext context) {
    return SvgPicture.string(_logoMarkSvg, width: size, height: size * (432 / 505));
  }
}

